// B"H
const fs = require('fs');
const path = require('path');
const { buildManifest } = require('../../geelooy/apps/tunnel/agent/rebuild-manifest.cjs');

/**
 * B"H
 * Chapter 380: The broad manifest bowed to the install manifest.
 * The tunnel-agent installer manifest is generated by the tunnel app itself.
 * This broader report calls that generator first, then records tunnel,
 * tunnel-control, and external library trees as an audit, not a second source.
 */
const ROOTS = [
  ['Tunnel app', 'geelooy/apps/tunnel'],
  ['Tunnel control app', 'geelooy/apps/tunnel-control'],
  ['Merkava executor external library', 'geelooy/scripts/awtsmoos/MerkavaExecutor'],
  ['Merkava AST parser external library', 'geelooy/scripts/awtsmoos/MerkavaASTParser']
];
const IGNORE_DIRS = new Set(['.git', 'node_modules', '.awtsmoos', '.tmp-connected-pagination']);
const IGNORE_PREFIX = ['.tmp-', 'tmp-', '__pycache__'];
const OUT_DIR = 'AI_THOUGHTS/runtime-stress';

function slash(value) { return String(value || '').replace(/\\/g, '/'); }
function exists(p) { try { return fs.existsSync(p); } catch (_) { return false; } }
function ignored(name) { return IGNORE_DIRS.has(name) || IGNORE_PREFIX.some(prefix => name.startsWith(prefix)); }
function walk(dir, base = dir, rows = []) {
  if (!exists(dir)) return rows;
  for (const name of fs.readdirSync(dir).sort((a, b) => a.localeCompare(b))) {
    if (ignored(name)) continue;
    const full = path.join(dir, name), st = fs.statSync(full), rel = slash(path.relative(base, full));
    rows.push({ path: rel, kind: st.isDirectory() ? 'dir' : 'file', bytes: st.isFile() ? st.size : 0 });
    if (st.isDirectory()) walk(full, base, rows);
  }
  return rows;
}
function section([label, root]) {
  const rows = walk(root);
  return { label, root, exists: exists(root), files: rows.filter(x => x.kind === 'file').length, dirs: rows.filter(x => x.kind === 'dir').length, bytes: rows.reduce((sum, x) => sum + x.bytes, 0), rows };
}
function treeLines(rows) { return rows.map(row => `${row.kind === 'dir' ? 'd' : 'f'} ${row.path}${row.kind === 'file' ? ` ${row.bytes}b` : '/'}`); }
function renderText(now, sections, agentManifest) {
  const lines = ['B"H', 'Tunnel rebuild manifest', `Generated: ${now}`, '', 'Install manifest source:', '- geelooy/apps/tunnel/agent/rebuild-manifest.cjs', `- agent files: ${agentManifest.files.length}`, '', 'Scope:'];
  for (const s of sections) lines.push(`- ${s.root} :: ${s.exists ? `${s.files} files, ${s.dirs} dirs, ${s.bytes} bytes` : 'MISSING'}`);
  lines.push('', 'External libraries that must be copied with tunnel runtime:', '- geelooy/scripts/awtsmoos/MerkavaExecutor', '- geelooy/scripts/awtsmoos/MerkavaASTParser', '', 'Tree:');
  for (const s of sections) lines.push('', `## ${s.label}: ${s.root}`, ...treeLines(s.rows));
  return lines.join('\n') + '\n';
}
function renderYaml(now, sections, agentManifest) {
  const lines = ['bh: "B\\"H"', `generated_at: ${JSON.stringify(now)}`, 'install_manifest:', '  generator: "geelooy/apps/tunnel/agent/rebuild-manifest.cjs"', `  files: ${agentManifest.files.length}`, 'roots:'];
  for (const s of sections) lines.push(`  - label: ${JSON.stringify(s.label)}`, `    path: ${JSON.stringify(s.root)}`, `    exists: ${s.exists}`, `    files: ${s.files}`, `    dirs: ${s.dirs}`, `    bytes: ${s.bytes}`);
  lines.push('external_libraries:', '  - "geelooy/scripts/awtsmoos/MerkavaExecutor"', '  - "geelooy/scripts/awtsmoos/MerkavaASTParser"', '');
  return lines.join('\n');
}
function main() {
  fs.mkdirSync(OUT_DIR, { recursive: true });
  const now = new Date().toISOString();
  const agentManifest = buildManifest();
  fs.writeFileSync('geelooy/apps/tunnel/agent/manifest.txt', agentManifest.text, 'utf8');
  const sections = ROOTS.map(section);
  fs.writeFileSync(path.join(OUT_DIR, 'manifest.txt'), renderText(now, sections, agentManifest));
  fs.writeFileSync(path.join(OUT_DIR, 'manifest.yaml'), renderYaml(now, sections, agentManifest));
  fs.writeFileSync(path.join(OUT_DIR, 'manifest.json'), JSON.stringify({ bh: 'B"H', generatedAt: now, installManifest: { generator: 'geelooy/apps/tunnel/agent/rebuild-manifest.cjs', files: agentManifest.files.length }, roots: sections }, null, 2));
  console.log(JSON.stringify({ ok: sections.every(s => s.exists), generatedAt: now, agentManifestFiles: agentManifest.files.length, roots: sections.map(s => ({ path: s.root, files: s.files, dirs: s.dirs, exists: s.exists })) }, null, 2));
}

main();
